changeSet.sql:
INSERT INTO aur_company (id, company_code, company_name, erp_type, api_parameters)
VALUES (1, 1, 'Varsayilan Sirket', 'LOCAL', '{"erpApiActive": false}'::jsonb);

INSERT INTO aur_role (id, role_name, company_code) VALUES
    (1, 'ROLE_ADMIN', 1),
    (2, 'ROLE_SEVKIYAT', 1),
    (3, 'ROLE_KABUL', 1);

INSERT INTO aur_menu_role_rel (menu_id, role_id)
SELECT m.id, 1 FROM aur_menu m
ON CONFLICT DO NOTHING;

INSERT INTO aur_menu_role_rel (menu_id, role_id)
SELECT m.id, 2 FROM aur_menu m WHERE m.id = 20 OR m.parent_menu_id = 20
ON CONFLICT DO NOTHING;

INSERT INTO aur_menu_role_rel (menu_id, role_id)
SELECT m.id, 3 FROM aur_menu m WHERE m.id = 10 OR m.parent_menu_id = 10
ON CONFLICT DO NOTHING;

UPDATE aur_user SET company_code = 1 WHERE login = 'admin';

INSERT INTO aur_user_role_rel (user_id, role_id)
SELECT u.id, 1 FROM aur_user u WHERE u.login = 'admin'
ON CONFLICT DO NOTHING;

INSERT INTO jhi_user_authority (user_id, authority_name)
SELECT u.id, 'COUNTER' FROM aur_user u WHERE u.login = 'admin'
ON CONFLICT DO NOTHING;

DELETE FROM jhi_user_authority WHERE user_id IN (SELECT id FROM aur_user WHERE login = 'user');
DELETE FROM aur_user WHERE login = 'user';
DELETE FROM jhi_user WHERE login = 'user';

SELECT setval('aur_company_seq', coalesce((SELECT max(id) FROM aur_company), 0) + 1, false);
SELECT setval('aur_role_seq', coalesce((SELECT max(id) FROM aur_role), 0) + 1, false);
